/* @lc app=leetcode id=2234 lang=kotlin */ class Solution { fun maximumBeauty(flowers: IntArray, newFlowers: Long, target: Int, full: Int, partial: Int): Long = flowers.map { minOf(it, target) }.sorted().let { a -> a.count { it == target }.let { fc -> a.filter { it < target }.let { b -> b.size.let { m -> if (m == 0) fc.toLong() * full else b.runningFold(0L) { s, x -> s + x }.let { pre -> (0..m).maxOf { k -> (k.toLong() * target - (pre[m] - pre[m - k])).let { cost -> if (cost > newFlowers) -1L else (newFlowers - cost).let { rem -> if (k == m) (fc + m).toLong() * full else generateSequence(1 to m - k) { (lo, hi) -> if (lo >= hi) null else ((lo + hi + 1) / 2).let { j -> if (b[j - 1].toLong() * j - pre[j] <= rem) j to hi else lo to j - 1 } }.last().first.let { j -> (fc + k).toLong() * full + minOf(target - 1L, (rem + pre[j]) / j) * partial } } } } } } } } } }